/* OpenLearnHub — Shared Styles */

:root {
  --primary: #0a0a23;
  --primary-foreground: #ffffff;
  --accent: #feac32;
  --accent-hover: #e59a2a;
  --link-blue: #002ead;
  --background: #ffffff;
  --background-alt: #f5f6f7;
  --foreground: #1b1b32;
  --muted: #f5f6f7;
  --muted-foreground: #6b7280;
  --border: #e5e7eb;
  --radius: 0.5rem;
  --font-sans: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", "Source Code Pro", monospace;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--background);
  color: var(--foreground);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

@media (min-width: 768px) {
  .container {
    padding: 0 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 2rem;
  }
}

/* Header */
.site-header {
  background: var(--primary);
  color: var(--primary-foreground);
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.site-header a {
  color: var(--primary-foreground);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 1rem;
}

.logo {
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--accent);
  color: var(--primary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 0.875rem;
}

.search-bar {
  display: none;
  flex: 1;
  max-width: 480px;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.08);
  color: var(--primary-foreground);
  font-size: 0.875rem;
  outline: none;
  transition: background 0.2s, border-color 0.2s;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.search-bar input:focus {
  background: rgba(255,255,255,0.12);
  border-color: rgba(255,255,255,0.3);
}

.desktop-nav {
  display: none;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.9375rem;
  font-weight: 500;
}

.desktop-nav a {
  opacity: 0.85;
  transition: opacity 0.15s;
}

.desktop-nav a:hover {
  opacity: 1;
  text-decoration: none;
}

.menu-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius);
  color: var(--primary-foreground);
  cursor: pointer;
  transition: background 0.15s;
}

.menu-toggle:hover {
  background: rgba(255,255,255,0.08);
}

.mobile-nav {
  display: none;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.5rem 0 1rem;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  padding: 0.625rem 0.75rem;
  border-radius: var(--radius);
  font-weight: 500;
  opacity: 0.9;
  transition: background 0.15s;
}

.mobile-nav a:hover {
  background: rgba(255,255,255,0.08);
  text-decoration: none;
}

@media (min-width: 768px) {
  .search-bar {
    display: block;
  }
  .desktop-nav {
    display: flex;
  }
  .menu-toggle {
    display: none;
  }
}

/* Banner */
.banner {
  background: var(--primary);
  color: var(--primary-foreground);
  text-align: center;
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.banner a {
  color: var(--accent);
  font-weight: 600;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.9375rem;
  cursor: pointer;
  border: none;
  transition: transform 0.1s, background 0.15s, box-shadow 0.15s;
  text-decoration: none;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: var(--accent);
  color: var(--primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
  text-decoration: none;
}

.btn-secondary {
  background: var(--primary);
  color: var(--primary-foreground);
}

.btn-secondary:hover {
  background: #14144a;
  text-decoration: none;
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--primary-foreground);
  text-decoration: none;
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}

.btn-ghost:hover {
  background: var(--muted);
  text-decoration: none;
}

/* Cards */
.card {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background: var(--muted);
}

.card-body {
  padding: 1rem;
}

/* Tag pills */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.tag-ai {
  background: #dbeafe;
  color: #1e40af;
}

.tag-web-scraping {
  background: #dcfce7;
  color: #166534;
}

.tag-databases {
  background: #f3e8ff;
  color: #6b21a8;
}

.tag-elasticsearch {
  background: #fef3c7;
  color: #92400e;
}

.tag-data-engineering {
  background: #fce7f3;
  color: #9d174d;
}

.tag-python {
  background: #dbeafe;
  color: #1e40af;
}

.tag-nodejs {
  background: #dcfce7;
  color: #166534;
}

.tag-google-sheets {
  background: #e0f2fe;
  color: #075985;
}

.tag-ai-automation {
  background: #ede9fe;
  color: #5b21b6;
}

.tag-general {
  background: var(--muted);
  color: var(--muted-foreground);
}

/* Article meta */
.article-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

.avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  font-weight: 700;
  color: var(--primary);
  flex-shrink: 0;
}

/* Section spacing */
.section {
  padding: 2.5rem 0;
}

@media (min-width: 768px) {
  .section {
    padding: 3.5rem 0;
  }
}

.section-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}

/* Grid */
.grid {
  display: grid;
  gap: 1.5rem;
}

.grid-1 {
  grid-template-columns: 1fr;
}

@media (min-width: 640px) {
  .grid-sm-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .grid-lg-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Footer */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.8);
  padding: 3rem 0 2rem;
  font-size: 0.875rem;
}

.site-footer a {
  color: rgba(255,255,255,0.7);
}

.site-footer a:hover {
  color: var(--primary-foreground);
}

.footer-grid {
  display: grid;
  gap: 2rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr;
  }
}

.footer-mission {
  max-width: 480px;
  line-height: 1.7;
}

.footer-heading {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--primary-foreground);
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-bottom {
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  text-align: center;
  color: rgba(255,255,255,0.5);
  font-size: 0.8125rem;
}

/* Donation tabs */
.donation-tabs {
  display: inline-flex;
  background: var(--background-alt);
  border-radius: var(--radius);
  padding: 0.25rem;
  gap: 0.25rem;
}

.donation-tab {
  padding: 0.5rem 1rem;
  border-radius: calc(var(--radius) - 0.125rem);
  font-weight: 600;
  font-size: 0.9375rem;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--foreground);
  transition: background 0.15s, color 0.15s;
}

.donation-tab.active {
  background: var(--background);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

/* FAQ Accordion */
.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  background: none;
  border: none;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--foreground);
  cursor: pointer;
  text-align: left;
}

.accordion-trigger:hover {
  color: var(--link-blue);
}

.accordion-icon {
  transition: transform 0.25s ease;
  flex-shrink: 0;
}

.accordion-item.open .accordion-icon {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.accordion-item.open .accordion-content {
  max-height: 500px;
  padding-bottom: 1rem;
}

.accordion-content p {
  color: var(--muted-foreground);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* Popular tags scroll */
.tags-scroll {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scrollbar-width: thin;
}

.tags-scroll::-webkit-scrollbar {
  height: 4px;
}

.tags-scroll::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 0.875rem;
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--foreground);
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
  text-decoration: none;
}

.tag-chip:hover {
  background: var(--muted);
  border-color: var(--muted-foreground);
  text-decoration: none;
}

.tag-chip-count {
  color: var(--muted-foreground);
  font-size: 0.8125rem;
}

/* Curriculum list */
.curriculum-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.curriculum-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: background 0.15s, border-color 0.15s;
  text-decoration: none;
  color: var(--foreground);
}

.curriculum-item:hover {
  background: var(--muted);
  border-color: var(--muted-foreground);
  text-decoration: none;
}

.curriculum-item i {
  color: var(--accent);
  flex-shrink: 0;
}

/* Stats grid */
.stats-grid {
  display: grid;
  gap: 1rem;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-card {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.stat-card i {
  color: var(--accent);
  margin-top: 0.125rem;
  flex-shrink: 0;
}

/* Hero featured */
.featured-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--primary);
  color: var(--primary-foreground);
}

.featured-card img {
  width: 100%;
  aspect-ratio: 21 / 9;
  object-fit: cover;
  opacity: 0.6;
}

.featured-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 2rem;
  background: linear-gradient(to top, rgba(10,10,35,0.95), rgba(10,10,35,0.4), transparent);
}

.featured-overlay .tag {
  margin-bottom: 0.75rem;
}

.featured-overlay h2 {
  font-size: 1.5rem;
  font-weight: 800;
  line-height: 1.25;
  max-width: 640px;
}

@media (min-width: 768px) {
  .featured-overlay h2 {
    font-size: 2rem;
  }
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1rem;
  font-size: 0.875rem;
  opacity: 0.85;
}

/* Initiatives */
.initiative-card {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.initiative-card i {
  color: var(--accent);
  margin-top: 0.125rem;
  flex-shrink: 0;
}

/* Section backgrounds */
.bg-alt {
  background: var(--background-alt);
}

/* Smooth fade-in for loaded articles */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in {
  animation: fadeInUp 0.35s ease-out forwards;
}

/* Utility */
.text-center { text-align: center; }
.mt-1 { margin-top: 0.25rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-3 { margin-top: 0.75rem; }
.mt-4 { margin-top: 1rem; }
.mt-6 { margin-top: 1.5rem; }
.mt-8 { margin-top: 2rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
.py-4 { padding-top: 1rem; padding-bottom: 1rem; }
.px-4 { padding-left: 1rem; padding-right: 1rem; }
.flex { display: flex; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.flex-wrap { flex-wrap: wrap; }
.w-full { width: 100%; }
.max-w-2xl { max-width: 42rem; }
.max-w-3xl { max-width: 48rem; }
.mx-auto { margin-left: auto; margin-right: auto; }
.text-sm { font-size: 0.875rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }
.text-2xl { font-size: 1.5rem; }
.text-3xl { font-size: 1.875rem; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }
.font-extrabold { font-weight: 800; }
.leading-tight { line-height: 1.25; }
.leading-relaxed { line-height: 1.625; }
.tracking-tight { letter-spacing: -0.02em; }
.text-muted { color: var(--muted-foreground); }

/* OpenLearnHub — Shared Scripts */

(function () {
  'use strict';

  // Mobile menu toggle
  const menuToggle = document.getElementById('menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');

  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', function () {
      mobileNav.classList.toggle('open');
      const isOpen = mobileNav.classList.contains('open');
      menuToggle.setAttribute('aria-expanded', String(isOpen));
      const icon = menuToggle.querySelector('i');
      if (icon) {
        icon.setAttribute('data-lucide', isOpen ? 'x' : 'menu');
        lucide.createIcons();
      }
    });
  }

  // Donation amount tabs
  const donationTabs = document.querySelectorAll('.donation-tab');
  const donationText = document.getElementById('donation-text');
  const donationSubLabel = document.getElementById('donation-sub-label');

  if (donationTabs.length && donationText) {
    donationTabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        donationTabs.forEach(function (t) { t.classList.remove('active'); });
        tab.classList.add('active');
        const amount = tab.dataset.amount;
        const hours = parseInt(tab.dataset.hours, 10);
        donationText.textContent =
          'Your $' + amount + ' donation will provide ' + hours.toLocaleString() +
          ' hours of learning to people around the world each month.';
        if (donationSubLabel) {
          donationSubLabel.textContent = 'Donating $' + amount + ' / month: edit amount · Secure donation';
        }
      });
    });
  }

  // FAQ accordion
  const accordionTriggers = document.querySelectorAll('.accordion-trigger');

  accordionTriggers.forEach(function (trigger) {
    trigger.addEventListener('click', function () {
      const item = trigger.closest('.accordion-item');
      const isOpen = item.classList.contains('open');

      // Optional: close others
      // document.querySelectorAll('.accordion-item.open').forEach(function (openItem) {
      //   if (openItem !== item) openItem.classList.remove('open');
      // });

      item.classList.toggle('open', !isOpen);
      trigger.setAttribute('aria-expanded', String(!isOpen));
    });
  });

  // Load more articles
  const loadMoreBtn = document.getElementById('load-more-btn');
  const articleGrid = document.getElementById('article-grid');

  if (loadMoreBtn && articleGrid) {
    const extraArticles = [
      {
        tag: 'JavaScript',
        tagClass: 'tag-general',
        title: 'Understanding Closures in JavaScript: A Practical Guide',
        author: 'Sarah Chen',
        time: '2 days ago',
        image: 'https://images.unsplash.com/photo-1579468118864-1b9ea3c0db4a?w=600&h=340&fit=crop'
      },
      {
        tag: 'Python',
        tagClass: 'tag-python',
        title: 'Building REST APIs with FastAPI: A Complete Tutorial',
        author: 'David Park',
        time: '3 days ago',
        image: 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=600&h=340&fit=crop'
      },
      {
        tag: 'React',
        tagClass: 'tag-general',
        title: 'React Server Components: What You Need to Know in 2024',
        author: 'Emily Roberts',
        time: '4 days ago',
        image: 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=600&h=340&fit=crop'
      },
      {
        tag: 'CSS',
        tagClass: 'tag-general',
        title: 'Modern CSS Layouts: Grid, Flexbox, and Container Queries',
        author: 'Alex Morgan',
        time: '5 days ago',
        image: 'https://images.unsplash.com/photo-1507721999472-8ed4421c4af2?w=600&h=340&fit=crop'
      },
      {
        tag: 'TypeScript',
        tagClass: 'tag-general',
        title: 'Advanced TypeScript Patterns for Large Codebases',
        author: 'James Wilson',
        time: '6 days ago',
        image: 'https://images.unsplash.com/photo-1516116216624-53e697fedbea?w=600&h=340&fit=crop'
      },
      {
        tag: 'Docker',
        tagClass: 'tag-general',
        title: 'Docker for Developers: From Zero to Production',
        author: 'Maria Garcia',
        time: '1 week ago',
        image: 'https://images.unsplash.com/photo-1605745341112-85968b19335b?w=600&h=340&fit=crop'
      }
    ];

    let loadCount = 0;

    loadMoreBtn.addEventListener('click', function () {
      const fragment = document.createDocumentFragment();
      const batch = extraArticles.slice(loadCount * 3, loadCount * 3 + 3);

      if (batch.length === 0) {
        loadMoreBtn.textContent = 'No more articles';
        loadMoreBtn.disabled = true;
        loadMoreBtn.classList.add('btn-ghost');
        loadMoreBtn.classList.remove('btn-primary');
        return;
      }

      batch.forEach(function (article, index) {
        const card = document.createElement('article');
        card.className = 'card animate-fade-in';
        card.style.animationDelay = (index * 80) + 'ms';
        card.innerHTML =
          '<img src="' + article.image + '" alt="" class="card-image" loading="lazy">' +
          '<div class="card-body">' +
            '<span class="tag ' + article.tagClass + '">#' + article.tag + '</span>' +
            '<h3 class="mt-3 font-bold leading-tight" style="font-size:1.0625rem;">' + article.title + '</h3>' +
            '<div class="article-meta">' +
              '<span class="avatar">' + article.author.split(' ').map(function (n) { return n[0]; }).join('') + '</span>' +
              '<span>' + article.author + '</span>' +
              '<span>·</span>' +
              '<span>' + article.time + '</span>' +
            '</div>' +
          '</div>';
        fragment.appendChild(card);
      });

      articleGrid.appendChild(fragment);
      loadCount++;

      if (loadCount * 3 >= extraArticles.length) {
        loadMoreBtn.textContent = 'No more articles';
        loadMoreBtn.disabled = true;
        loadMoreBtn.classList.add('btn-ghost');
        loadMoreBtn.classList.remove('btn-primary');
      }
    });
  }

  // Initialize Lucide icons
  if (typeof lucide !== 'undefined') {
    lucide.createIcons();
  }
})();
